css:
.loader { display: flex; align-items: center; gap: calc(var(--loader-size) * .07); width: var(--loader-size); animation: twPulse calc(var(--loader-speed) * 1.6) cubic-bezier(.4, 0, .6, 1) infinite; }
.loader .avatar { flex: none; width: calc(var(--loader-size) * .24); height: calc(var(--loader-size) * .24); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 42%, transparent); }
.loader .rows { display: flex; flex: 1; flex-direction: column; gap: calc(var(--loader-size) * .05); }
.loader .rows i { height: calc(var(--loader-size) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 26%, transparent); }
.loader .rows i:first-child { width: 88%; }
.loader .rows i:last-child { width: 56%; }
@keyframes twPulse { 50% { opacity: .4; } }
